package com.stark.automation.utils;
import com.stark.automation.core.driver.DriverFactory; import java.nio.file.Files; import java.nio.file.Path; import java.time.LocalDateTime; import java.time.format.DateTimeFormatter; import org.openqa.selenium.OutputType; import org.openqa.selenium.TakesScreenshot;
public final class ScreenshotCapture { private ScreenshotCapture() { } public static byte[] capture(String testName) { try { byte[] image = ((TakesScreenshot) DriverFactory.getDriver()).getScreenshotAs(OutputType.BYTES); Path directory = Path.of("target", "screenshots"); Files.createDirectories(directory); Files.write(directory.resolve(testName + "-" + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss")) + ".png"), image); return image; } catch (Exception ignored) { return new byte[0]; } } }
